{"content": "param(
  [string]$Endpoint = "https://example.com"
)

$ErrorActionPreference = 'Stop'

function Invoke-Mcp {
  param([string]$Method, [hashtable]$Params, [int]$Id = 1)
  $body = @{ jsonrpc = '2.0'; id = $Id; method = $Method } | ConvertTo-Json -Compress
  $r = curl.exe -s --noproxy * --connect-timeout 5 --max-time 60 -X POST $Endpoint `
        -H "Content-Type: application/json" `
        -H "Accept: application/json, text/event-stream" `
        -H "MCP-Protocol-Version: 2025-11-25" `
        -d $body
  return $r
}

# initialize (session may be stateless; harmless if repeated)
Invoke-Mcp -Method 'initialize' -Params @{
  protocolVersion = '2025-11-25'
  capabilities    = @{}
  clientInfo      = @{ name = 'dsh-agent'; version = '1.0' }
} -Id 1 | Out-Null

$raw = Invoke-Mcp -Method 'tools/list' -Id 2
$raw | Out-File -FilePath (Join-Path $PSScriptRoot 'ios-mcp-tools-raw.json') -Encoding utf8

# parse SSE-framed or plain json
$json = $raw
if ($raw -match '(?s)^event:\s*message\s*\r?\ndata:\s*(.*)$') { $json = $Matches[1].Trim() }
try {
  $obj = $json | ConvertFrom-Json
} catch {
  Write-Host "PARSE-FAIL (first 400 chars):"
  Write-Host $raw.Substring(0, [Math]::Min(400, $raw.Length))
  exit 2
}

$rows = foreach ($t in $obj.result.tools) {
  $req = @()
  if ($t.inputSchema -and $t.inputSchema.required) { $req = $t.inputSchema.required }
  $props = @()
  if ($t.inputSchema -and $t.inputSchema.properties) { $props = $t.inputSchema.properties.PSObject.Properties.Name }
  [pscustomobject]@{
    Tool        = $t.name
    Required    = ($req -join ',')
    Properties  = ($props -join ',')
    Description = ($t.description -replace '\s+', ' ').Substring(0, [Math]::Min(160, ($t.description -replace '\s+', ' ').Length))
  }
}

$rows | Format-Table -AutoSize -Wrap
"`nTOTAL TOOLS: $($rows.Count)"
", "file_path": "/workspace/ios-mcp-list-tools.ps1"}

